<?php namespace App\Http\Controllers\client;use App\Http\Controllers\Controller;use App\Models\client\PncReview;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\File;class PncReviewController extends Controller{public function index(){$reviews=PncReview::where('client_id',Auth::guard('client')->id())->latest()->paginate(12);return view('panel.client.review.index',compact('reviews'));}public function store(Request $r){$c=Auth::guard('client')->user();$d=$this->data($r,true);$d['image']=$this->image($r,$c);PncReview::create($d+['client_id'=>$c->id,'status'=>'published']);return back()->with('success','Review added.');}public function update(Request $r,$id){$c=Auth::guard('client')->user();$x=PncReview::where('client_id',$c->id)->findOrFail($id);$d=$this->data($r,false);if($r->hasFile('image'))$d['image']=$this->image($r,$c);$x->update($d);return back()->with('success','Review updated.');}public function delete($id){$x=PncReview::where('client_id',Auth::guard('client')->id())->findOrFail($id);$x->delete();return response()->json(['status'=>'success']);}private function data($r,$img){return $r->validate(['name'=>'required|string|max:120','designation'=>'nullable|string|max:120','rating'=>'required|integer|min:1|max:5','message'=>'required|string|max:1000','image'=>[$img?'required':'nullable','image','mimes:jpg,jpeg,png,webp','max:2048']]);}private function image($r,$c){$k=str_replace(['/','\\','..'],'',trim((string)$c->api_key));$d="$k/uploads/reviews";File::ensureDirectoryExists(public_path($d),0755,true);$f=$r->file('image');$n=time().'_'.uniqid().'.'.$f->getClientOriginalExtension();$f->move(public_path($d),$n);return "$d/$n";}}